import app from 'flarum/forum/app';
import Search from 'flarum/forum/components/Search';
import ItemList from 'flarum/common/utils/ItemList';
import UsersSearchSourceWithoutInternalRouting from './UsersSearchSourceWithoutInternalRouting';
import extractText from 'flarum/common/utils/extractText';
export default class UserSearch extends Search {
  sourceItems() {
    const items = new ItemList();
    if (app.forum.attribute('canSearchUsers')) {
      items.add('users', new UsersSearchSourceWithoutInternalRouting(user => {
        this.attrs.onsubmit(user);
        this.clear();
      }));
    }
    return items;
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    this.setPlaceholder();
  }
  onupdate(vnode) {
    super.onupdate(vnode);
    this.setPlaceholder();
  }
  setPlaceholder() {
    const input = this.element.querySelector('input');
    if (input) {
      input.placeholder = extractText(app.translator.trans('fof-author-change.forum.search.placeholder'));
      input.setAttribute('aria-label', input.placeholder);
    }
  }
}
flarum.reg.add('fof-author-change', 'forum/components/UserSearch', UserSearch);